// Assume 'GPIO_PORTA_DIR' is the direction register for Port A
// and 'GPIO_PORTA_DATA' is the data register for Port A.
// 'GPIO_PIN_0' represents the bit for Pin 0.

// 1. Configure Pin 0 of Port A as OUTPUT
GPIO_PORTA_DIR |= (1 << GPIO_PIN_0); 

// 2. Set Pin 0 HIGH (e.g., turn on an LED)
GPIO_PORTA_DATA |= (1 << GPIO_PIN_0);

// 3. Set Pin 0 LOW (e.g., turn off an LED)
GPIO_PORTA_DATA &= ~(1 << GPIO_PIN_0);

